	]);
	const testYears = $derived(
		[...new Set(doc.features.map((f) => (f.test_years ?? doc.test_years).join("–")))].join(", "),
	);

	function pick(code: string) {
		selected = code;
		document.querySelector(`[data-code="${code}"]`)?.scrollIntoView({ block: "nearest", behavior: "smooth" });
	}
</script>

