<!-- Line chart in the tradingview chart family: canvas background, --border grid, price axis on the
     right, value tags on the axis in the series color. Lines use non-scaling strokes so the SVG
     stretches to the pane width. `from`/`to` zoom to an index window (brush), `cursor` is a shared
     crosshair index (bindable, so sibling charts follow it), `band` shades an index range (year hover).
     Time labels thin to the measured width (≥ 56px apart) and the edge ones stay inside the pane;
     a scale label under a value tag hides, as on the live price scale. -->
<script lang="ts">
	type Series = { label: string; values: number[]; color: string; area?: boolean; dashed?: boolean };

	let {
		series,
		labels,
		ticks,
		height = 260,
		log = false,
		format = (v: number) => String(v),
		tagFormat,
		from = 0,
		to,
		cursor = $bindable(null),
		band = null,
		role,
	}: {
		series: Series[];
		labels: string[];
		ticks: number[];
		height?: number;
		log?: boolean;
		format?: (v: number) => string;
		tagFormat?: (v: number) => string;
		from?: number;
		to?: number;
		cursor?: number | null;
		band?: [number, number] | null;
		role?: string;
	} = $props();

	const W = 1000;
	const AXIS = 64;
	const PAD = 12;

	const last = $derived(to ?? labels.length - 1);
	const span = $derived(Math.max(last - from, 1));
	const visible = $derived(series.flatMap((s) => s.values.slice(from, last + 1)));
	const lo = $derived(Math.min(...visible));
	const hi = $derived(Math.max(...visible));
	const shownTicks = $derived(ticks.filter((t) => t >= lo && t <= hi));
	const tf = (v: number) => (log ? Math.log(v) : v);

	function y(v: number) {
		const t = (tf(v) - tf(lo)) / (tf(hi) - tf(lo) || 1);
		return height - PAD - t * (height - 2 * PAD);
	}
	function x(i: number) {
		return ((i - from) / span) * W;
	}
	function line(values: number[]) {
		return values
			.slice(from, last + 1)
			.map((v, k) => `${k === 0 ? "M" : "L"}${x(from + k).toFixed(1)},${y(v).toFixed(1)}`)
			.join(" ");
	}
	function area(values: number[]) {
		const base = y(Math.max(lo, Math.min(hi, log ? lo : 0)));
		return `${line(values)} L${x(last).toFixed(1)},${base.toFixed(1)} L0,${base.toFixed(1)} Z`;
	}
	const tag = $derived(tagFormat ?? format);
	const pct = (i: number) => ((i - from) / span) * 100;

	// Year ticks: January of each year in the window, thinned so labels keep ≥ 56px between them.
	let plotWidth = $state(0);
	const maxLabels = $derived(plotWidth ? Math.max(2, Math.floor(plotWidth / 56)) : 8);
	const xTicks = $derived.by(() => {
		const out: { index: number; label: string }[] = [];
		for (let i = from; i <= last; i++)
			if (labels[i]?.endsWith("-01")) out.push({ index: i, label: labels[i].slice(0, 4) });
		if (!out.length) {
			const every = Math.max(1, Math.ceil(span / Math.min(6, maxLabels)));
			for (let i = from; i <= last; i += every) out.push({ index: i, label: labels[i] });
			return out;
		}
		const step = Math.ceil(out.length / maxLabels);
		return out.filter((_, k) => k % step === 0);
	});
	// The crosshair's date plate replaces the time labels it would cover (live time scale behavior).
	const underCursor = (i: number) =>
		cursor != null && cursor >= from && cursor <= last && Math.abs(pct(i) - pct(cursor)) * plotWidth < 6000;
	const edge = (i: number) => (pct(i) < 3 ? "start" : pct(i) > 97 ? "end" : undefined);

	// Axis tags show the cursor value when the crosshair is on, else the last visible value.
	const at = $derived(cursor != null && cursor >= from && cursor <= last ? cursor : last);
	const tags = $derived.by(() => {
		const out = series
			.map((s) => ({ label: s.label, color: s.color, value: s.values[at], top: y(s.values[at]) - 10 }))
			.sort((a, b) => a.top - b.top);
		for (let i = 1; i < out.length; i++) out[i].top = Math.max(out[i].top, out[i - 1].top + 21);
		return out;
	});
	const covered = (t: number) => tags.some((g) => Math.abs(g.top + 10 - y(t)) < 16);

	function move(event: PointerEvent) {
		const box = (event.currentTarget as HTMLElement).getBoundingClientRect();
		const f = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
		cursor = from + Math.round(f * span);
	}
