+/** Axis date label with dots: a day 01 must not be read as a January tick. */
+export function dateLabel(ms: number): string {
+	const d = new Date(ms);
+	const pad = (n: number) => String(n).padStart(2, "0");
+	return `${d.getUTCFullYear()}.${pad(d.getUTCMonth() + 1)}.${pad(d.getUTCDate())}`;
+}
+
+export interface ScreenCurveView {
+	rule: number[];
+	hold: number[];
+	ticks: number[];
+	labels: string[];
+	lo: number;
+	hi: number;
+}
+
+const asPercent = (v: number) => Math.round(v * 100 * 1e6) / 1e6;
+
+/** Carry a missing point forward (a gap keeps the last known value) before scaling to percent. */
+function toPercentSeries(values: (number | null)[] | undefined): number[] {
+	const out: number[] = [];
+	let last = 0;
+	for (const v of values ?? []) {
+		if (v != null && Number.isFinite(v)) last = asPercent(v);
+		out.push(last);
+	}
+	return out;
+}
+
+/** Chart-ready view of a trial's curve: percent values, date labels and shared value ticks. */
+export function curveView(trial: ScreenTrial | null | undefined): ScreenCurveView | null {
+	const curve = trial?.curve;
+	if (!curve || curve.t.length < 2) return null;
+	const rule = toPercentSeries(curve.rule);
+	const hold = toPercentSeries(curve.hold);
+	const values = [...rule, ...hold];
+	const lo = Math.min(...values);
+	const hi = Math.max(...values);
+	return {
+		rule,
+		hold,
+		ticks: niceTicks(lo, hi),
+		labels: curve.t.map(dateLabel),
+		lo,
+		hi,
+	};
+}
+
+export interface ScreenRuleTile {
+	id: string;
+	group: "entry" | "fill" | "exit";
+	name: string;
+	label: string;
+	tip: string;
+}
+
+/**
+ * The rule the screen actually tested, as tiles: which side a value above the threshold takes, which
+ * indicator it is, what a fill costs and how long a position is held.
+ */
+export function screenRule(doc: ScreenDoc, feature: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
+	const folds = trial.folds ?? [];
+	const signs = [...new Set(folds.map((fold) => Math.sign(fold.train_sign)))].filter((s) => s !== 0);
+	const fixed = doc.fixed_sign;
+	const sign = fixed ?? trial.train_sign ?? signs.at(-1) ?? 1;
+	const long = sign >= 0;
+	const changed = fixed == null && signs.length > 1;
+	const fixedWord = fixed == null ? null : fixed > 0 ? "+1" : "−1";
+	const ruleWord = `지표가 기준(${fixedWord ?? (sign >= 0 ? "+1" : "−1")}) 위면`;
+	const tiles: ScreenRuleTile[] = [
+		{
+			id: "direction",
+			group: "entry",
+			name: `기준 위면 ${long ? "롱" : "숏"}`,
+			label: changed ? "부호 바뀜" : long ? "순방향" : "역추세",
+			tip: fixedWord
+				? `${ruleWord} ${long ? "사고" : "팔고"} 기준 아래면 반대로 간다. 학습 구간 부호를 ${fixedWord}로 고정한 문서라 해마다 뒤집히지 않는다.`
+				: changed
+					? `${ruleWord} ${long ? "사고" : "팔고"} 기준 아래면 반대로 간다. 다만 학습 구간 부호가 해마다 바뀌어, 어느 해의 부호를 믿을지가 관건이다.`
+					: `${ruleWord} ${long ? "사고" : "팔고"} 기준 아래면 반대로 간다. 학습 구간의 부호가 ${sign >= 0 ? "+1" : "−1"}이라${long ? " 값이 클수록 롱" : " 값이 클수록 숏"}이다.`,
+		},
+		{
+			id: "indicator",
+			group: "entry",
+			name: featureName(feature),
+			label: feature.tradeable === false ? "참고 지표" : "매매 지표",
+			tip: feature.tradeable === false
+				? `${featureDef(feature)} 체결이 실시간으로 공개되지 않아 실제로 따라 살 수 없다. 방향성만 참고한다.`
+				: featureDef(feature),
+		},
+	];
+	if (doc.regime === "down")
+		tiles.push({
+			id: "regime",
+			group: "entry",
+			name: "하락 국면만",
+			label: "국면 게이트",
+			tip: "종가가 200일 평균 아래인 날만 점수를 매기고 매매한다. 국면이 바뀌면 신호가 없을 수 있다.",
+		});
+	tiles.push(
+		{
+			id: "fill",
+			group: "fill",
+			name: `편도 ${(doc.cost_per_side * 1e4).toFixed(0)}bp`,
+			label: "비용",
+			tip: `한 번 사고팔 때마다 편도 ${(doc.cost_per_side * 1e4).toFixed(0)}bp를 뺀다. 보수적으로 실제의 2배를 적용했다.`,
+		},
+		{
+			id: "hold",
+			group: "exit",
+			name: `${trial.h}${doc.unit} 보유`,
+			label: "보유 기간",
+			tip: `신호가 나온 뒤 ${trial.h}${doc.unit === "H" ? "시간" : "일"} 동안 들고 있다가 청산한다.`,
+		},
+	);
+	return tiles;
+}
+
 export function num(v: number | null | undefined, digits = 3): string {
 	if (v == null || !Number.isFinite(v)) return "—";
 	const s = v.toFixed(digits);
 	return v > 0 ? `+${s}` : s.replace("-", "−");

