<!-- A leading-indicator screening experiment (plan 261109 S7) in the experiment page's layout: header chips,
     the 후보 card (Gate flow over the screen's gates, then the candidate table with screening columns), the
     atomic-run matrix (candidate × test year, cell = that year's IC), and the structure section's status line.
     Every verdict, gate result and number is quant-signal's own; nothing is recomputed here. -->
<script lang="ts">
	import HashIcon from "@lucide/svelte/icons/hash";
	import ListOrderedIcon from "@lucide/svelte/icons/list-ordered";
	import LockIcon from "@lucide/svelte/icons/lock";
	import TargetIcon from "@lucide/svelte/icons/target";
	import * as Table from "$lib/components/ui/table/index.js";
	import AppShell from "./app-shell.svelte";
	import Board from "./board/board.svelte";
	import Card from "./board/card.svelte";
	import ChipTabs from "./chip-tabs.svelte";
	import { VIRTUAL_FACT } from "./data";
	import GateFlow from "./gate-flow.svelte";
	import InfoTip from "./info-tip.svelte";
	import RunMatrix from "./run-matrix.svelte";
	import {
		FAMILY_LABEL,
		featureDef,
		featureName,
		leadTrial,
		num,
		pctOf,
		screenGates,
		screenMatrix,
		verdictKind,
		type ScreenDoc,
	} from "./screen";
	import VerdictBadge from "./verdict-badge.svelte";

	let { doc, moreExperiments = [] }: { doc: ScreenDoc; moreExperiments?: { id: string; name: string }[] } = $props();

	const STEPS = ["초안", "봉인됨", "실행중", "평가완료", "판정", "모의·섀도", "실전승인"];
	const current = $derived(doc.state === "평가완료" ? 3 : 4);
	const STEP_NOTE: Record<string, string> = {
		초안: "시험할 지표와 합격선을 적는다",
		봉인됨: "합격선 파일을 잠근다. 바꾸려면 새 실험",
		실행중: "지표와 시계를 조합해 시험한다",
		평가완료: "합격선 결과가 나왔다",
		판정: "하나라도 채택되면 연구를 통과하고, 없으면 기각한다",
		"모의·섀도": "채택한 지표를 미리 등록하고, 잠근 구간과 모의로 확인한다",
		실전승인: "운영자가 다시 확인한다",
	};
	const stepFact = $derived({
		icon: ListOrderedIcon,
		label: `단계 ${current + 1}/${STEPS.length} · ${doc.state}`,
		tip: `헤더의 단계 칩은 지금 어디인지 보여 준다. ${STEPS.map((s, i) => `${i < current ? "✓" : i === current ? "▶" : i + 1} ${s}: ${STEP_NOTE[s]}`).join(" / ")}`,
	});
	const unitWord = $derived(doc.unit === "H" ? "시간" : "일");
	const screenFact = $derived({
		icon: TargetIcon,
		label: `순위 IC · 비용 ${(doc.cost_per_side * 1e4).toFixed(0)}bp`,
		tip: `이 순위 IC 칩은 비교 기준이다. 지표가 BTC의 다음 ${doc.horizons.join("·")}${unitWord} 수익률 순위를 맞히는지(0이면 무관)를 보고, 수익은 학습 구간 중앙값 위는 사고 아래는 파는 규칙으로 편도 ${(doc.cost_per_side * 1e4).toFixed(0)}bp(보수적 2배)와 실제 펀딩을 빼 계산했다. 시행 ${doc.trials_total}회이고, DSR은 앞선 실험까지 ${doc.trials_counted}회로 깎았다.${doc.regime === "down" ? " 종가가 200일 평균 아래인 날만 점수를 매기고 매매한다." : ""}`,
	});
	const sealTip = $derived(
		`헤더의 봉인 칩이 켜지면 지표, 시계, 합격선을 바꿀 수 없다. 바꾸려면 새 실험을 만든다.${doc.note ? ` 봉인 메모: ${doc.note}` : ""}`,
	);

	const gates = $derived(screenGates(doc));
	let selected = $state<string | null>(null);
	let horizon = $state<string>("lead");
	const matrix = $derived(screenMatrix(doc, horizon === "lead" ? "lead" : Number(horizon)));
	const horizonTabs = $derived([
		{ id: "lead", label: "판정 시계", title: "후보마다 판정 사유가 가리키는 시계" },
		...doc.horizons.map((h) => ({ id: String(h), label: `${h}${doc.unit}` })),
	]);
	const testYears = $derived(
		[...new Set(doc.features.map((f) => (f.test_years ?? doc.test_years).join("–")))].join(", "),
	);

	function pick(code: string) {
		selected = code;
		document.querySelector(`[data-code="${code}"]`)?.scrollIntoView({ block: "nearest", behavior: "smooth" });
	}
</script>

