 export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

+/** The trial for horizon `h`; "lead" and horizons the feature lacks fall back to its lead trial. */
+export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
+	if (h === "lead") return leadTrial(f);
+	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
+}
+
+/** Round value-axis ticks (1/2/5 × 10ⁿ) covering [lo, hi], so a zero line is always a tick. */
+export function niceTicks(lo: number, hi: number, count = 5): number[] {
+	if (!Number.isFinite(lo) || !Number.isFinite(hi)) return [];
+	if (lo > hi) [lo, hi] = [hi, lo];
+	const span = hi - lo;
+	if (span === 0) return [Math.round(lo * 1e6) / 1e6];
+	const raw = span / Math.max(count, 1);
+	const power = 10 ** Math.floor(Math.log10(raw));
+	const fraction = raw / power;
+	const step = (fraction < 1.5 ? 1 : fraction < 3.5 ? 2 : fraction < 7.5 ? 5 : 10) * power;
+	const start = Math.ceil(lo / step) * step;
+	const end = Math.floor(hi / step) * step;
+	const out: number[] = [];
+	for (let v = start; v <= end + step * 1e-9; v += step) out.push(Math.round(v * 1e6) / 1e6);
+	return out;
+}
+
+/** Axis date label with dots: a day 01 must not be read as a January tick. */
+export function dateLabel(ms: number): string {
+	const d = new Date(ms);
+	const pad = (n: number) => String(n).padStart(2, "0");
+	return `${d.getUTCFullYear()}.${pad(d.getUTCMonth() + 1)}.${pad(d.getUTCDate())}`;
+}
+
+export interface ScreenCurveView {
